/**
 * A segmented field for a length of time (`design/components/duration-input.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/duration-input.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { createMemo, createUniqueId, mergeProps, onCleanup, onMount, type JSX } from 'solid-js'

import {
  Each,
  agentDuration,
  agentMember,
  claimSlot,
  commitDuration,
  createCell,
  createDerived,
  durationDraft,
  durationKey,
  durationSegments,
  elementRef,
  itemOf,
  typeIntoDuration,
  watchEffect,
  type Defaults,
  type DurationUnit,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/controls/duration-input.module.css'

export interface DurationInputMessages {
  /** What an empty count says as its value to assistive software. */
  empty: string
}

export interface DurationInputProps {
  'aria-describedby'?: string
  /**
   * Wired by FormField; set directly only when there is no visible label.
   */
  'aria-label'?: string
  'aria-labelledby'?: string
  'aria-required'?: boolean
  defaultValue?: number | null
  disabled?: boolean
  id?: string
  invalid?: boolean
  /**
   * Sets the digits, the unit words and each count's name.
   */
  locale?: string
  /**
   * The most seconds a commit holds; none by default.
   */
  max?: number
  /**
   * The one word the member writes itself.
   */
  messages?: DurationInputMessages
  /**
   * The fewest seconds a commit holds; `0` by default.
   */
  min?: number
  /**
   * Posts the committed value as whole seconds, such as `"604800"`.
   */
  name?: string
  onChange?: (seconds: number | null) => void
  /**
   * Keeps the counts focusable, but arrows and digits do not edit.
   */
  readOnly?: boolean
  size?: 'sm' | 'md' | 'lg'
  /**
   * Which counts show, in any order; they are drawn largest first. Days, hours and minutes by
   * default.
   */
  units?: readonly DurationUnit[]
  /**
   * Whole seconds, and `null` for the empty field. `onChange` reports committed values: a step
   * as it fires, typed digits when focus leaves the field or on Enter, each held inside `min`
   * and `max`.
   */
  value?: number | null
}

/** A segmented field for a length of time. */
export default function DurationInput(given: DurationInputProps): JSX.Element {
  const props = mergeProps(
    {
      messages: (() => ({ empty: 'Empty' }))(),
      size: 'md',
      disabled: false,
      readOnly: false,
      invalid: false,
    } as Defaults<DurationInputProps, 'messages' | 'size' | 'disabled' | 'readOnly' | 'invalid'>,
    claimSlot(given, 'group'),
  )
  const uid = createUniqueId()
  const field = elementRef<HTMLElement>()
  const browserLanguage = createCell(undefined as string | undefined)
  const draft = createCell(
    durationDraft(props.value !== undefined ? props.value : (props.defaultValue ?? null), {
      units: props.units,
      min: props.min,
      max: props.max,
      locale: props.locale ?? browserLanguage.value ?? 'en-US',
    }),
  )
  const typed = createCell('')
  const reported = createCell(
    (props.value !== undefined ? props.value : (props.defaultValue ?? null)) as number | null,
  )
  const language = createDerived(() => props.locale ?? browserLanguage.value ?? 'en-US')
  const fieldOptions = createDerived(() => ({
    units: props.units,
    min: props.min,
    max: props.max,
    locale: language.value,
  }))
  const editable = createDerived(() => !props.disabled && !props.readOnly)
  const segments = createDerived(() =>
    durationSegments(draft.value, fieldOptions.value, props.messages),
  )
  const posted = createDerived(() => (props.value !== undefined ? props.value : reported.value))
  const moveSegment = createDerived(() => (from: EventTarget | null, by: number): void => {
    if (!(from instanceof HTMLElement)) return
    const all = [
      ...(from.closest('[role="group"]')?.querySelectorAll<HTMLElement>('[data-segment]') ?? []),
    ]
    all[all.indexOf(from) + by]?.focus()
  })
  const commit = createDerived(() => (next: ReturnType<typeof durationDraft>): void => {
    const result = commitDuration(next, reported.value, fieldOptions.value)
    draft.value = result.draft
    if (result.changed) {
      reported.value = result.value
      props.onChange?.(result.value)
    }
  })
  const act = createDerived(
    () =>
      (action: ReturnType<typeof durationKey>, from: EventTarget | null): void => {
        if (action.kind === 'move') {
          typed.value = ''
          moveSegment.value(from, action.by)
        } else if (action.kind === 'type') {
          typed.value = action.typed
          draft.value = action.draft
          if (action.advance) moveSegment.value(from, 1)
        } else if (action.kind === 'step') {
          typed.value = ''
          commit.value(action.draft)
        } else if (action.kind === 'commit') {
          typed.value = ''
          commit.value(draft.value)
        }
      },
  )
  const segmentKeys = createDerived(
    () =>
      (event: KeyboardEvent, segment: ReturnType<typeof durationSegments>[number]): void => {
        const action = durationKey(
          draft.value,
          segment.unit,
          typed.value,
          event,
          {
            editable: editable.value,
            rtl: getComputedStyle(event.currentTarget as HTMLElement).direction === 'rtl',
          },
          fieldOptions.value,
        )
        if (action.kind === 'pass') return
        event.preventDefault()
        act.value(action, event.currentTarget)
      },
  )
  const segmentInput = createDerived(
    () =>
      (event: Event, segment: ReturnType<typeof durationSegments>[number]): void => {
        event.preventDefault()
        if (!editable.value) return
        const data = (event as InputEvent).data ?? ''
        for (const key of data) {
          const next = typeIntoDuration(
            draft.value,
            segment.unit,
            typed.value,
            key,
            fieldOptions.value,
          )
          typed.value = next.typed
          draft.value = next.draft
          if (next.advance) {
            moveSegment.value(event.currentTarget, 1)
            break
          }
        }
      },
  )
  const leave = createDerived(() => (event: FocusEvent): void => {
    const to = event.relatedTarget
    if (to instanceof Node && (event.currentTarget as HTMLElement).contains(to)) return
    typed.value = ''
    commit.value(draft.value)
  })
  const effect1 = () => {
    browserLanguage.value = globalThis.navigator?.language
  }
  onMount(effect1)
  const effect2 = () => {
    void (
      props.value !== undefined &&
      ((draft.value = durationDraft(props.value, fieldOptions.value)),
      (reported.value = props.value))
    )
  }
  watchEffect(
    createMemo(() => props.value),
    effect2,
    false,
  )
  let release3: (() => void) | undefined
  const effect3 = () => {
    release3?.()
    const ran = agentMember({
      member: 'DurationInput',
      element: () => field.value,
      state: () => ({
        value: posted.value,
        disabled: props.disabled,
        invalid: props.invalid,
        readonly: props.readOnly,
      }),
      actions: {
        set: {
          argument: 'number',
          run: (value) =>
            (() => {
              if (props.readOnly) throw new Error('The field is read-only.')
              commit.value(
                durationDraft(agentDuration(value, fieldOptions.value), fieldOptions.value),
              )
            })(),
        },
        clear: () =>
          (() => {
            if (props.readOnly) throw new Error('The field is read-only.')
            commit.value({})
          })(),
      },
    })
    release3 = () => {
      ran()
    }
  }
  onMount(effect3)
  onCleanup(() => release3?.())
  return (
    <div
      class={styles.field}
      role="group"
      id={props.id}
      aria-label={props['aria-label']}
      aria-labelledby={props['aria-labelledby']}
      aria-describedby={props['aria-describedby']}
      aria-disabled={props.disabled ? 'true' : undefined}
      data-size={props.size}
      data-disabled={props.disabled ? '' : undefined}
      data-invalid={props.invalid ? '' : undefined}
      data-readonly={props.readOnly ? '' : undefined}
      data-member="duration-input"
      onfocusout={($event: FocusEvent) => leave.value($event)}
      ref={field.attach}
    >
      {/* segments */}
      <div class={styles.segments}>
        <Each of={segments.value} by={(segment) => segment.unit} renew>
          {(segment) => (
            <div class={styles.quantity}>
              {segment.wordFirst ? (
                <span class={styles.unit} aria-hidden="true">
                  {segment.word}
                </span>
              ) : null}
              {/* segment */}
              <div
                class={styles.segment}
                role="spinbutton"
                id={`${uid}-${segment.unit}`}
                aria-label={segment.name}
                aria-labelledby={
                  props['aria-labelledby']
                    ? `${props['aria-labelledby']} ${uid}-${segment.unit}`
                    : undefined
                }
                aria-describedby={props['aria-describedby']}
                aria-valuenow={segment.value}
                aria-valuemin={segment.min}
                aria-valuemax={segment.max}
                aria-valuetext={segment.valueText}
                aria-required={props['aria-required'] ? 'true' : undefined}
                aria-readonly={props.readOnly ? 'true' : undefined}
                aria-disabled={props.disabled ? 'true' : undefined}
                aria-invalid={props.invalid ? 'true' : undefined}
                contenteditable={editable.value ? 'true' : undefined}
                inputmode="numeric"
                spellcheck="false"
                tabindex={props.disabled ? undefined : '0'}
                data-segment={segment.unit}
                data-placeholder={segment.placeholder ? '' : undefined}
                data-disabled={props.disabled ? '' : undefined}
                onfocus={() => (typed.value = '')}
                onkeydown={($event: KeyboardEvent) => segmentKeys.value($event, itemOf(segment))}
                onbeforeinput={($event: InputEvent) => segmentInput.value($event, itemOf(segment))}
              >
                {segment.text}
              </div>
              {!segment.wordFirst ? (
                <span class={styles.unit} aria-hidden="true">
                  {segment.word}
                </span>
              ) : null}
            </div>
          )}
        </Each>
      </div>
      {props.name !== undefined ? (
        <input
          type="hidden"
          name={props.name}
          value={posted.value === null ? '' : String(posted.value)}
          disabled={props.disabled ? true : undefined}
        />
      ) : null}
    </div>
  )
}

DurationInput.controlKind = 'group'
